    FIXTURE_WALLET_INSUFFICIENT_BALANCE = 2004
    FIXTURE_WALLET_WRONG_DESTINATION = 2005
    FIXTURE_SOOTH_WALLET_SENDER_NOT_OWNER = 2101
    FIXTURE_SOOTH_WALLET_AMOUNT_NON_POSITIVE = 2102
    FIXTURE_SOOTH_WALLET_INSUFFICIENT_BALANCE = 2103
    FIXTURE_SOOTH_WALLET_SENDER_NOT_WALLET = 2104
    FIXTURE_SOOTH_WALLET_INSUFFICIENT_BURN_VALUE = 2105
    FIXTURE_SOOTH_MASTER_SENDER_NOT_ADMIN = 2201
    FIXTURE_SOOTH_MASTER_AMOUNT_NON_POSITIVE = 2202
    FIXTURE_SOOTH_MASTER_SENDER_NOT_WALLET = 2203
    FIXTURE_SOOTH_MASTER_INSUFFICIENT_SUPPLY = 2204
}

// Shared TEP-74 jetton interop for the Sooth TON fund-holding contracts (AMM / order engine /
// launchpad). The outgoing JettonTransfer body (opcode 0x0f8a7ea5) and the attached-value helper
// are byte-identical across all three, so they live here as a single source of truth.
//
// NOTE: JettonTransferNotification (0x7362d09c) is intentionally NOT shared. Its forwardPayload
// field type has diverged by design — the launchpad declares it `cell?` so it can re-parse the
// creation/yield payload as a standalone cell, while the AMM and order engine read the tail
// inline as RemainingBitsAndRefs. Each contract therefore keeps its own notification struct.
//
// The opcode is wire-significant; do NOT change it.

struct (0x0f8a7ea5) JettonTransfer {
    queryId: uint64
    amount: coins
    destination: address
    responseDestination: address
    customPayload: cell?
    forwardTonAmount: coins
    forwardPayload: RemainingBitsAndRefs
}

// Minimum TON to attach to a message that will emit one outgoing JettonTransfer: the transfer's
// own carried value plus a fixed overhead for the sending contract's compute/storage. The
// forwardTonAmount is contained inside jettonTransferValue, so it is not added again here.
fun requiredJettonSendValue(jettonTransferValue: coins, _forwardTonAmount: coins) {
    return jettonTransferValue + ton("0.005");
}

// Shared market-lifecycle + outcome enum for all Sooth TON contracts.
//
// This is the single source of truth for the cross-contract lifecycle labels and the
// INVALID outcome. The registry is the canonical six-label authority; the launchpad
// (graduation/trial) and the adjudicator (resolve/attest/settle/dispute) drive subsets of
// the same enum and notify the registry. Previously each of those three contracts hand-copied
// these constants — identical today, but a drift would be a settlement-routing bug. Importing
// this file keeps them in lockstep. Helpers are plain (not `get fun`) and tree-shake to zero
// in any contract that doesn't call a given one, so importing the full set is free.
//
// Values are wire-significant (carried in lifecycle messages + getters); do NOT renumber.

fun lifecycleBonding(): uint8 {
    return 0;
}

fun lifecycleLive(): uint8 {
    return 1;
}

fun lifecycleTrialExpired(): uint8 {
    return 2;
}

fun lifecycleResolving(): uint8 {
    return 3;
}

fun lifecycleAttested(): uint8 {
    return 4;
}

fun lifecycleSettled(): uint8 {
    return 5;
}

fun invalidOutcome(): uint8 {
    return 2;
}
